Definition smpd (A P : Z) (ws : list word) (pad : word) : mpd := mkMPD A 1 (Z.of_nat (length ws)) P ws pad LStatic.

(* [comment removed for export] *)
Definition grp_sw (id : Z) (ca : curve_addrs) (ONE A : Z) (idpad pP pA pB pX pY pZ pN hpad : word) : ecp_grp :=
  mkGRP id idpad
        (smpd (A + 8) (ca_P ca) (cP id) pP)
        (if has_A id then smpd (A + 24) (ca_A ca) (cA id) pA else mpd_init (A + 24) pA)
        (smpd (A + 40) (ca_B ca) (cB id) pB)
        (mkPT (smpd (A + 56) (ca_GX ca) (cGX id) pX) (smpd (A + 72) (ca_GY ca) (cGY id) pY) (smpd (A + 88) ONE [Z_to_bv 64 1] pZ))
        (smpd (A + 104) (ca_N ca) (cN id) pN)
        (core_bitlen (cP id) (Z.of_nat (length (cP id)))) (core_bitlen (cN id) (Z.of_nat (length (cN id))))
        1 hpad (ca_modp ca) 0 0 0 (ca_T ca) 0.

